#define DCACHE_CACHE_CTRL       (DCACHE_BASE + 0x0000)
#define DCACHE_CACHE_STATUS     (DCACHE_BASE + 0x0004)
#define DCACHE_STB_TIMEOUT_CTRL (DCACHE_BASE + 0x0008)

/* DCACHE_CACHE_CTRL bit fields */

#define DCACHE_CACHE_EN_BIT         (1 << 0)
#define DCACHE_CACHE_ENTRY_THRESH   (7 << 4)   /* stb_entry = 7 */
#define DCACHE_STB_TIMEOUT_EN_BIT   (1 << 8)
#define DCACHE_CACHE_BYPASS_BIT     (1 << 16)

/* DCACHE_CACHE_STATUS bit fields */

#define DCACHE_INIT_FINISH_BIT      (1 << 0)

