 *
 * Description:
 *   Register the UART driver as /dev/console and /dev/ttyS0.
 *
 ****************************************************************************/

void riscv_serialinit(void)
{
  /* Register the console as /dev/console */

  uart_register("/dev/console", &g_console_port);

  /* Register the same UART as /dev/ttyS0 */

  uart_register("/dev/ttyS0", &g_console_port);
}

/****************************************************************************
 * Name: up_putc
 *
 * Description:
 *   Output one character to the console UART.
 *   This is used by the OS for debug output after the serial driver is
 *   initialized.
 *
 ****************************************************************************/

void up_putc(int ch)
{
  struct rv1126b_uart_s *priv = (struct rv1126b_uart_s *)g_console_port.priv;
  uint32_t base = priv->base;

  /* Wait until TX FIFO is not full */

  while (!(getreg32(UART_USR(base)) & RV1126B_UART_USR_TFNF))
    {
    }

  /* Write the character */

  putreg32((uint32_t)ch, UART_THR(base));
}

/****************************************************************************
 * NuttX - RV1126B System Tick Timer Driver
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.  See the NOTICE file distributed with
 * this work for additional information regarding copyright ownership.
 * The ASF licenses this file to you under the Apache License, Version
 * 2.0 (the "License"); you may not use this file except in compliance
 * with the License.  You may obtain a copy of the License at
 *
 *   http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS,
 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or
 * implied.  See the License for the specific language governing
 * permissions and limitations under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <stdbool.h>
#include <assert.h>
#include <errno.h>

#include <nuttx/arch.h>
#include <nuttx/clock.h>
#include <nuttx/timers/arch_timer.h>

#include "riscv_internal.h"
#include "hardware/rv1126b_timer.h"
#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* MTIME register access macros */

#define CTIMER_MTIME_CTRL   (RV1126B_CTIMER_BASE + RV1126B_CTIMER_MTIME_CTRL)
#define CTIMER_MTIME_DIV    (RV1126B_CTIMER_BASE + RV1126B_CTIMER_MTIME_DIV)
#define CTIMER_MTIME        (RV1126B_CTIMER_BASE + RV1126B_CTIMER_MTIME)
#define CTIMER_MTIMEH       (RV1126B_CTIMER_BASE + RV1126B_CTIMER_MTIMEH)
#define CTIMER_MTIMECMP     (RV1126B_CTIMER_BASE + RV1126B_CTIMER_MTIMECMP)
#define CTIMER_MTIMECMPH    (RV1126B_CTIMER_BASE + RV1126B_CTIMER_MTIMECMPH)

/* Timer configuration:
 * HPMCU frequency = 396 MHz
 * Divider = 1000
 * Effective timer clock = 396 MHz / 1000 = 396 kHz
 * For 100 Hz tick: 396000 / 100 = 3960 counts per tick
 */

#define RV1126B_MTIME_DIV_VALUE   1000
#define RV1126B_MTIME_TICK_VALUE  (RV1126B_MTIME_FREQ / RV1126B_MTIME_DIV_VALUE / 100)

/****************************************************************************
 * Private Data
 ****************************************************************************/

static uint64_t g_mtimecmp_step = RV1126B_MTIME_TICK_VALUE;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: rv1126b_timer_stop
 *
 * Description:
 *   Stop the MTIME timer by clearing the enable bit.
 *
 ****************************************************************************/

static void rv1126b_timer_stop(void)
{
  uint32_t regval;

  regval = getreg32(CTIMER_MTIME_CTRL);
  regval &= ~RV1126B_MTIME_CTRL_EN;
  putreg32(regval, CTIMER_MTIME_CTRL);
}

/****************************************************************************
 * Name: rv1126b_timer_start
 *
 * Description:
 *   Start the MTIME timer by setting the enable bit.
 *
 ****************************************************************************/

static void rv1126b_timer_start(void)
{
  uint32_t regval;

  regval = getreg32(CTIMER_MTIME_CTRL);
  regval |= RV1126B_MTIME_CTRL_EN;
  putreg32(regval, CTIMER_MTIME_CTRL);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: up_timer_initialize
 *
 * Description:
 *   Configure the MTIME timer to generate periodic system tick interrupts
 *   at 100 Hz (CONFIG_USEC_PER_TICK = 10000 usec).
 *
 *   This function is called during early OS initialization before the
 *   scheduler is started.
 *
 ****************************************************************************/

void up_timer_initialize(void)
{
  /* Stop the timer first */

  rv1126b_timer_stop();

  /* Reset MTIME counter to 0 */

  putreg32(0, CTIMER_MTIME);
  putreg32(0, CTIMER_MTIMEH);

  /* Reset MTIMECMP to 0 */

  putreg32(0, CTIMER_MTIMECMP);
  putreg32(0, CTIMER_MTIMECMPH);

  /* Set the divider to divide the core clock by 1000 */

  putreg32(RV1126B_MTIME_DIV_VALUE, CTIMER_MTIME_DIV);

  /* Set MTIMECMP to the first tick value */

  putreg32(RV1126B_MTIME_TICK_VALUE, CTIMER_MTIMECMP);
  putreg32(0, CTIMER_MTIMECMPH);

  /* Enable the MIP_MTIP bit in the mie CSR to allow timer interrupts */

  set_csr(mie, MIP_MTIP);

  /* Start the timer */

  rv1126b_timer_start();
}

/****************************************************************************
 * Name: up_timer_int
 *
 * Description:
 *   Advance the MTIMECMP register by one tick period.  This is called
 *   from the timer interrupt handler to acknowledge the interrupt and
 *   schedule the next tick.
 *
 ****************************************************************************/

void up_timer_int(void)
{
  uint64_t mtimecmp;

  /* Temporarily disable timer interrupt to avoid race condition */

  clear_csr(mie, MIP_MTIP);

  /* Read current MTIMECMP value (64-bit) */

  mtimecmp = (uint64_t)getreg32(CTIMER_MTIMECMPH) << 32;
  mtimecmp |= getreg32(CTIMER_MTIMECMP);

  /* Advance by one tick period */

  mtimecmp += g_mtimecmp_step;

  /* Write new MTIMECMP value */

  putreg32((uint32_t)(mtimecmp & 0xffffffff), CTIMER_MTIMECMP);
  putreg32((uint32_t)(mtimecmp >> 32), CTIMER_MTIMECMPH);

  /* Re-enable timer interrupt */

  set_csr(mie, MIP_MTIP);
}

/****************************************************************************
 * Name: hardware_initialize
 *
 * Description:
 *   Tramsition to the OSINIT_HARDWARE state.
 *
 ****************************************************************************/

static void hardware_initialize(void)
{
  /* Initialize tasking data structures */

  task_initialize();

  /* Initialize the instrument function */

  instrument_initialize();

  /* Initialize the file system (needed to support device drivers) */

  fs_initialize();

  /* Initialize the interrupt handling subsystem (if included) */

  irq_initialize();

  /* Initialize the POSIX timer facility (if included in the link) */

  clock_initialize();

#ifndef CONFIG_DISABLE_POSIX_TIMERS
  timer_initialize();
#endif

  /* Initialize the signal facility (if in link) */

  nxsig_initialize();

#if !defined(CONFIG_DISABLE_MQUEUE) || !defined(CONFIG_DISABLE_MQUEUE_SYSV)
  /* Initialize the named message queue facility (if in link) */

  nxmq_initialize();
#endif

#ifdef CONFIG_NET
  /* Initialize the networking system */

  net_initialize();
#endif

#ifndef CONFIG_BINFMT_DISABLE
  /* Initialize the binfmt system */

  binfmt_initialize();
#endif

  /* Initialize Hardware Facilities *****************************************/

  /* The processor specific details of running the operating system
   * will be handled here.  Such things as setting up interrupt
   * service routines and starting the clock are some of the things
   * that are different for each  processor and hardware platform.
   */

  up_initialize();

  /* Initialize common drivers */

  drivers_initialize();

#ifdef CONFIG_BOARD_EARLY_INITIALIZE
  /* Call the board-specific up_initialize() extension to support
   * early initialization of board-specific drivers and resources
   * that cannot wait until board_late_initialize.
   */

  boards_trace_begin();
  board_early_initialize();
  boards_trace_end();
#endif

  /* Hardware resources are now available */

  g_nx_initstate = OSINIT_HARDWARE;
  sched_trace_mark("HARDWARE");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: nx_start
 *
 * Description:
 *   This function is called to initialize the operating system and to spawn
 *   the user initialization thread of execution.  This is the initial entry
 *   point into NuttX.
 *
 * Input Parameters:
 *   None
 *
 * Returned Value:
 *   Does not return.
 *
 ****************************************************************************/

void nx_start(void)
{
#ifdef CONFIG_SMP
  int i;
#endif

  /* Boot up is complete */

  g_nx_initstate = OSINIT_BOOT;
  sched_trace_begin();
  sinfo("Entry\n");

  /* Head of ready-to-run/assigned task lists valid */

  tasklist_initialize();

  /* The memory manager has been initialized */

  memory_initialize();

  /* MCU-specific hardware is initialized */

  hardware_initialize();

  /* Setup for Multi-Tasking ************************************************/

  /* Announce that the CPU0 IDLE task has started */

  sched_note_start(&this_cpu_var(g_idletcb));

  /* Initialize stdio for the IDLE task of each CPU */

  /* Create stdout, stderr, stdin on the CPU0 IDLE task.  These
   * will be inherited by all of the threads created by the CPU0
   * IDLE task.
   */

  DEBUGVERIFY(group_setupidlefiles());

#ifdef CONFIG_SMP
  for (i = 1; i < CONFIG_SMP_NCPUS; i++)
    {
      /* Clone stdout, stderr, stdin from the CPU0 IDLE task. */

      DEBUGVERIFY(group_setuptaskfiles(&per_cpu_var_smp(g_idletcb, i),
                                        NULL, true));
    }

  /* Start all CPUs *********************************************************/

  /* A few basic sanity checks */

  DEBUGASSERT(this_cpu() == 0);

  /* Then start the other CPUs */

  DEBUGVERIFY(nx_smp_start());

#endif /* CONFIG_SMP */

  /* Bring Up the System ****************************************************/

  /* The OS is fully initialized and we are beginning multi-tasking */

  g_nx_initstate = OSINIT_OSREADY;
  sched_trace_mark("OSREADY");

  /* Create initial tasks and bring-up the system */

  nx_bringup();

  /* Enter to idleloop */

  g_nx_initstate = OSINIT_IDLELOOP;
  sched_trace_mark("IDLELOOP");

  /* Let other threads have access to the memory manager */

  sched_trace_end();
  sched_unlock();

  /* The IDLE Loop **********************************************************/

  /* When control is return to this point, the system is idle. */

  sinfo("CPU0: Beginning Idle Loop\n");
#ifndef CONFIG_DISABLE_IDLE_LOOP
  for (; ; )
    {
      /* Perform any processor-specific idle state operations */

      up_idle();
    }
#endif
}

